using UnityEngine; using System;
namespace HonourWar { public sealed class HonourWarCombatComponent:MonoBehaviour { public int Level=1,SkillPoints; public float HP=100,MaxHP=100,SP=100,MaxSP=100; public int[] SkillLevels=new int[8]; public string LastCombatMessage=""; public event Action<string> CombatMessage; public bool ActivateSkill(int index,HonourWarMonster target){if(index<0||index>=8){LastCombatMessage="skill index invalid";return false;} int cost=5+SkillLevels[index]*2;if(SP<cost){LastCombatMessage=$"skill {index} failed: insufficient SP";CombatMessage?.Invoke(LastCombatMessage);return false;} if(target==null||!target.IsAlive){LastCombatMessage=$"skill {index} failed: no target";CombatMessage?.Invoke(LastCombatMessage);return false;} SP-=cost; int damage=Mathf.Max(1,20+Level*4+SkillLevels[index]*8); target.TakeDamage(damage); LastCombatMessage=$"skill {index} impact confirmed for {damage}"; CombatMessage?.Invoke(LastCombatMessage); return true;} public void RestoreVitals(){HP=MaxHP;SP=MaxSP;} public void GainExperience(int amount){Level=Mathf.Clamp(Level+Mathf.Max(0,amount)/100,1,250); if(Level%5==0)SkillPoints++;} } }